"""SessionWorkflow, code version v2c: v1c plus the unguarded policy step (generated by engine/gen_variants.py from v1). Holds ids, cursors and counters only; every effect is an activity.
Turn = read event from Postgres, (stand-in) compute, idempotent external effect, append result event.
Multi-tenant: the tenant travels in the state and is passed to every activity; a doorbell for an event id that is not
of this tenant and session is rejected before anything is read or marked.
History is bounded on EVERY path: the continue-as-new check is the first thing every loop iteration does, so a long
approval wait, a rollup wait, a backlog or an idle session all reach it; idle and approval polling back off."""
import asyncio
from datetime import timedelta

from temporalio import workflow
from temporalio.common import RetryPolicy
from temporalio.exceptions import ActivityError, ApplicationError
from temporalio.exceptions import TimeoutError as TemporalTimeout

with workflow.unsafe.imports_passed_through():
    from engine import keys as keys_mod
    from engine import waits as waits_mod

CODE = "v2c"
AT = dict(start_to_close_timeout=timedelta(seconds=8),
          retry_policy=RetryPolicy(initial_interval=timedelta(milliseconds=500), maximum_interval=timedelta(seconds=5),
                                   non_retryable_error_types=["InvalidInput", "SubjectErased", "Poison"]))
TURN_STC = timedelta(minutes=10)   # turn activities that keep failing for 10 minutes raise an alert and are retried later
MAX_CARRY = 40       # pending ids carried across continue-as-new (the rest are recovered by reconcile)
DONE_CARRY = 40      # recently processed ids carried (a late duplicate doorbell must not run a turn twice)
DEFAULTS = {"done": [], "pend": [], "finish": False, "rejected": 0, "dead": 0, "dead_failed": 0, "alert": "",
            "erased": False, "approval_req": "", "last_eid": "", "reconcile_s": 20, "reconcile_max_s": 600,
            "approval_poll_s": 10, "approval_poll_max_s": 900, "stop_after_rollups": 0, "approval_deadline_ms": 0,
            "poisoned": [], "approval_poll_cur": 0, "reconcile_cur": 0}


async def act(name, *args):
    return await workflow.execute_activity(name, args=list(args), **AT)


async def act_turn(name, *args):
    return await workflow.execute_activity(name, args=list(args), schedule_to_close_timeout=TURN_STC, **AT)


def now_ms():
    return int(workflow.now().timestamp() * 1000)


def seqkey(e):
    p = keys_mod.parse_event_id(e)
    return p[2] if p else 0


@workflow.defn(name="SessionWorkflow")
class SessionWorkflow:
    @workflow.init
    def __init__(self, st: dict):
        self.st = dict(st)
        for k, v in DEFAULTS.items():
            self.st.setdefault(k, list(v) if isinstance(v, list) else v)
        self.pending = list(self.st["pend"])
        self.done_list = list(self.st["done"])
        self.done = set(self.done_list)
        self.poisoned = set(self.st["poisoned"])        # inputs whose dead-letter failed: skipped, alert raised
        self.defer_n = 0
        self.approved = False
        self.finish = bool(self.st["finish"])
        self.sig = 0
        self.rotate = False
        self.last_rec_ms = 0
        self.rec_cur = self.st["reconcile_cur"] or self.st["reconcile_s"]        # current (backed-off) interval, carried
        self.apr_cur = self.st["approval_poll_cur"] or self.st["approval_poll_s"]   # current (backed-off) poll, carried
        self.more = False  # last reconcile returned a full batch: more unprocessed inputs may be waiting in Postgres

    @workflow.signal
    def turn(self, event_id: str):
        self.sig += 1
        if not keys_mod.belongs_to(self.st["tenant"], self.st["sid"], event_id):
            self.st["rejected"] += 1       # foreign or malformed id: nothing is read, marked or queued
            return
        if event_id in self.done or event_id in self.pending:
            return
        self.pending.append(event_id)
        self.pending.sort(key=seqkey)

    @workflow.signal
    def rotate_now(self, ref: str):
        self.rotate = True

    @workflow.signal
    def approve(self, ref: str):
        self.approved = True

    @workflow.signal
    def finish_now(self, ref: str):
        self.finish = True

    @workflow.query
    def progress(self) -> dict:
        return {"turns": self.st["turns_done"], "sig": self.st["signals_seen"] + self.sig, "code": CODE}

    @workflow.query
    def status(self) -> dict:
        """Operator view: the alert state surfaced by bounded retries and failed dead-letters."""
        return {"alert": self.st["alert"], "dead": self.st["dead"], "dead_failed": self.st["dead_failed"],
                "rejected": self.st["rejected"], "approval": self.st["approval"], "turns": self.st["turns_done"]}

    # ---- one turn: the only place the command sequence matters for in-flight sessions
    async def _steps(self, eid):
        t, sid = self.st["tenant"], self.st["sid"]
        digest = await act_turn("turn_read", t, sid, eid, sorted(self.poisoned)[:20])
        if digest == "defer":
            return "defer"
        await act_turn("turn_policy", t, sid, eid)
        key = await act_turn("turn_effect", t, sid, eid)
        res = await act_turn("turn_append", t, sid, eid, digest, key, CODE)
        return "ok" if res[1] else "dup"

    async def _requeue(self, eid):
        if eid not in self.pending:
            self.pending.append(eid)
            self.pending.sort(key=seqkey)

    async def _turn(self, eid):
        """Returns 'ok' (counted), 'dup' (already processed: not counted), 'dead' (dead-lettered), 'rejected' (not an
        input of this session: nothing written, nothing marked) or 'defer' (try again, older inputs first)."""
        t, sid = self.st["tenant"], self.st["sid"]
        try:
            r = await self._steps(eid)
            if r == "defer":
                await self._reconcile()                    # sequence order: older unprocessed inputs go first
                await self._requeue(eid)
                if not any(seqkey(e) < seqkey(eid) for e in self.pending):
                    # nothing older turned up, yet Postgres says an older input is unprocessed: back off, do not spin
                    self.defer_n += 1
                    self.st["alert"] = f"blocked_by_older_input:{eid}"
                    await workflow.sleep(min(2 ** self.defer_n, 60))
                else:
                    self.defer_n = 0
            else:
                self.defer_n = 0
            return r
        except ActivityError as e:
            cause = e.cause
            typ = cause.type if isinstance(cause, ApplicationError) else None
            if isinstance(cause, TemporalTimeout):         # the activity kept failing for TURN_STC: alert, retry later
                self.st["alert"] = f"activity_timeout:{eid}"
                await workflow.sleep(30)
                await self._requeue(eid)
                return "defer"
            if typ == "InvalidInput":                      # not an existing turn_input of this session
                self.st["rejected"] += 1
                return "rejected"
            if typ not in ("SubjectErased", "Poison"):
                raise
            try:
                await act("dead_letter", t, sid, eid, typ)   # poison path: recorded, never retried, never blocks the session
            except ActivityError:                          # the dead-letter path failing must not fail the workflow
                self.st["alert"] = f"dead_letter_failed:{typ}:{eid}"
                self.st["dead_failed"] += 1
                self.poisoned.add(eid)                     # skipped from now on; newer inputs are NOT blocked behind it
                if typ == "SubjectErased":                 # no event can be appended for an erased subject: end the session
                    self.st["erased"] = True
                return "stuck"
            self.st["dead"] += 1
            if typ == "SubjectErased":
                self.st["erased"] = True
            return "dead"

    async def _reconcile(self):
        ids = await act("reconcile", self.st["tenant"], self.st["sid"])
        self.last_rec_ms = now_ms()
        self.more = len(ids) >= 20
        new = [e for e in ids if e not in self.pending and e not in self.done and e not in self.poisoned]
        if new or self.pending:
            self.rec_cur = self.st["reconcile_s"]          # found work: poll at the base rate again
        else:
            self.rec_cur = min(self.rec_cur * 2, self.st["reconcile_max_s"])   # idle: back off
        self.pending.extend(new)
        self.pending.sort(key=seqkey)

    def _want_can(self):
        info = workflow.info()
        cl = self.st.get("can_len", 0)
        return self.rotate or info.is_continue_as_new_suggested() or (cl and info.get_current_history_length() >= cl)

    async def _maybe_can(self):
        """Continue-as-new from the main method only, handlers drained, with a truncated carried list (the rest is
        recovered by reconcile): a backlog, an approval wait or an idle session can never block it."""
        if not self._want_can():
            return
        st = self.st
        tq = await act("get_config", "target_queue")
        await workflow.wait_condition(workflow.all_handlers_finished)
        st["pend"] = [e for e in self.pending if e not in self.done][:MAX_CARRY]
        st["done"] = self.done_list[-DONE_CARRY:]
        st["poisoned"] = sorted(self.poisoned)[:20]
        st["approval_poll_cur"] = self.apr_cur           # the backoff survives a boundary
        st["reconcile_cur"] = self.rec_cur
        st["finish"] = self.finish
        st["signals_seen"] += self.sig
        st["cans"] += 1
        st["hist_max"] = max(st["hist_max"], workflow.info().get_current_history_length())
        if tq and tq != workflow.info().task_queue:
            workflow.continue_as_new(st, task_queue=tq)
        workflow.continue_as_new(st)

    @workflow.run
    async def run(self, st: dict) -> dict:
        st = self.st
        t, sid = st["tenant"], st["sid"]
        if st["rollup_s"] and not st["rollup_deadline_ms"]:
            st["rollup_deadline_ms"] = now_ms() + int(st["rollup_s"] * 1000)
        await self._reconcile()
        while True:
            if self.finish and not self.pending:
                break
            if st["erased"]:
                break
            if st["expected_turns"] and st["turns_done"] >= st["expected_turns"]:
                break
            if st.get("stop_after_rollups") and st["rollups"] >= st["stop_after_rollups"]:
                break
            await self._maybe_can()
            # approval gate bound to ONE request id; Postgres decides, the signal is only a doorbell
            if st["approval_at"] and st["approval"] == "none" and st["turns_done"] >= st["approval_at"]:
                rid, dl = await act("approval_request", t, sid, st["last_eid"] or "start", int(st["approval_to_s"] * 1000))
                st["approval"], st["approval_req"], st["approval_deadline_ms"] = "waiting", rid, dl
            if st["approval"] == "waiting":
                res = await act("approval_resolve", t, sid, st["approval_req"])   # check first: a rebuilt session resumes at once
                if res == "pending":
                    # the doorbell is the fast path; the poll backs off (a lost doorbell costs at most the current poll)
                    remaining = (st["approval_deadline_ms"] - now_ms()) / 1000
                    if not self.approved:
                        try:
                            await workflow.wait_condition(lambda: self.approved,
                                                          timeout=waits_mod.approval_wait_s(remaining, self.apr_cur))
                        except asyncio.TimeoutError:
                            self.apr_cur = min(self.apr_cur * 2, st["approval_poll_max_s"])
                    self.approved = False
                else:
                    st["approval"] = res
                continue
            if st["rollup_s"] and now_ms() >= st["rollup_deadline_ms"]:
                await act("rollup", t, sid, st["rollup_deadline_ms"])   # keyed by the scheduled deadline, not a counter
                st["rollups"] += 1
                st["rollup_deadline_ms"] = max(st["rollup_deadline_ms"] + int(st["rollup_s"] * 1000), now_ms() + 1000)
                continue
            if st["reconcile_s"] and now_ms() - self.last_rec_ms >= self.rec_cur * 1000:
                await self._reconcile()   # a lost doorbell cannot hang an input for longer than the current interval
                continue
            if self.pending:
                eid = self.pending.pop(0)
                if eid not in self.done and eid not in self.poisoned:
                    r = await self._turn(eid)
                    if r in ("ok", "dup", "dead", "stuck"):
                        self.done.add(eid)
                        self.done_list.append(eid)
                    if r in ("ok", "dead"):
                        st["turns_done"] += 1
                        st["last_eid"] = eid
                    if r != "rejected":
                        self.rec_cur = st["reconcile_s"]
            elif self.more:
                await self._reconcile()
            else:
                timeouts = []
                if st["rollup_s"]:
                    timeouts.append((st["rollup_deadline_ms"] - now_ms()) / 1000)
                if st["reconcile_s"]:
                    timeouts.append((self.last_rec_ms + self.rec_cur * 1000 - now_ms()) / 1000)
                timeout = max(min(timeouts), 0.001) if timeouts else None
                try:
                    await workflow.wait_condition(lambda: bool(self.pending) or self.finish or self.rotate, timeout=timeout)
                except asyncio.TimeoutError:
                    pass
                if self.pending:
                    self.rec_cur = st["reconcile_s"]
        if not st["erased"]:
            await act("finish_session", t, sid, st["turns_done"])
        await workflow.wait_condition(workflow.all_handlers_finished)
        return {"turns": st["turns_done"], "sig": st["signals_seen"] + self.sig, "cans": st["cans"],
                "rollups": st["rollups"], "approval": st["approval"], "rejected": st["rejected"], "dead": st["dead"],
                "dead_failed": st["dead_failed"], "alert": st["alert"], "erased": st["erased"], "code": CODE}
